    /** If not empty, for a specific doc reference(rare) */
    DocReference?: string | undefined;
    /** If not empty, for a specific document process type(Common) */
    DocTypeKey?: string | undefined;
    /** When true, has read permission */
    ReadOK?: boolean;
    /** When true, has read permission */
    InsOK?: boolean;
    /** When true, has read permission */
    UpdOK?: boolean;
    /** When true, has read permission */
